/* SKILL_LIBRARY_START: project methods use the existing canvas visual language. */
const skillbook=document.createElement('dialog');skillbook.id='skillbook';skillbook.setAttribute('aria-label','能力与工作流');document.body.append(skillbook);
const SB={projectId:null,query:'',category:'',kind:'',page:1,openOnly:false,includeHistorical:false,entries:[],known:new Map(),recommendations:[],stats:null,status:null,total:0,kinds:[],categories:[],detail:null,guide:null,searchAC:null,recommendAC:null,detailAC:null,epoch:0,busy:false,notice:'',goalDrafts:new Map()};
const sbKinds={'skill-entry':'Skill','workflow':'工作流','instruction':'指令','agent-role':'角色','cookbook':'示例','local-method':'适配方法','workflow-platform':'工作流平台','article':'文章','collection':'方法集合','historical-example':'历史示例','plugin-entry':'插件条目','example':'示例','guide':'指南','role-collection':'角色集合','guide-chapter':'指南章节'};
const sbProject=()=>P(SB.projectId);
const sbRefs=p=>Array.isArray(p?.skillRefs)?p.skillRefs:[];
const sbNeeds=p=>({id:p.id,name:p.name,goal:p.summary||'',roles:[p.coordinator,...p.members].map(m=>m.role||''),fileTypes:[...new Set(state.files.filter(f=>f.pid===p.id).map(f=>f.name.split('.').pop().toLowerCase()))].slice(0,30)});
async function sbApi(action,data={},signal){const r=await fetch('/api/studio/library',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...data}),signal});const d=await r.json();if(!r.ok)throw new Error(d.error||'资料库暂时不可用');return d;}
const sbRemember=entries=>entries.forEach(e=>SB.known.set(e.id,e));
const sbReview=e=>e.bodyReadOn?'指南已读取':e.review==='adapted-method'?'本地适配方法':e.review==='body-reviewed'?'有正文阅读记录':e.review==='section-reviewed'?'有章节阅读记录':'仅目录索引';
function sbPins(p){return sbRefs(p).map(r=>`<span class="sb-pin" title="${esc(r.mode==='guide'?'已读取，保留此版本':'项目参考')}" style="--c:${p.ui.color}">${esc(r.title)}${r.mode==='guide'?' · 指南':''}</span>`).join('');}
const sbRenderTop=renderTop;renderTop=function(){sbRenderTop();$('#tools').insertAdjacentHTML('beforeend',`<button data-sb-open aria-label="打开能力库">${icon('layers')}能力库</button>`)};
const sbRenderPan=renderPan;renderPan=function(){sbRenderPan();if(panK==='proj'){const p=P(panId);if(p)$('#pan').insertAdjacentHTML('beforeend',`<div class="lab">项目方法</div><div class="sb-pins">${sbPins(p)||'<span class="lab">按项目目标寻找合适的方法</span>'}</div><button data-sb-open="${p.id}">${icon('layers',14)}能力与工作流</button>`)}};
const sbRenderRoom=renderRoom;renderRoom=function(){sbRenderRoom();const p=P(state.room);if(!p)return;$('#room .rh').insertAdjacentHTML('beforeend',`<button data-sb-open="${p.id}">${icon('layers')}能力库${sbRefs(p).length?' · '+sbRefs(p).length:''}</button>`);$('#room .det').insertAdjacentHTML('beforeend',`<div class="lab">项目方法 · 仅作参考或 Prompt 指南</div><div class="sb-pins">${sbPins(p)||'<span class="lab">尚未选择</span>'}</div>`)};
CAT.push(['library.open','打开项目能力库','projectId?'],['library.search','搜索 Skill 或工作流','query,category?'],['library.recommend','按项目目标初筛方法','projectId'],['library.add','把已展示的条目加入项目参考','projectId,resourceId'],['library.remove','移除项目方法引用','projectId,resourceId']);
ACT['library.open']=a=>{sbOpen(a.projectId);return'已打开能力库'};
ACT['library.search']=a=>{SB.query=String(a.query||'');SB.category=String(a.category||'');sbOpen(undefined,false);return'正在搜索能力库'};
ACT['library.recommend']=a=>{sbOpen(rp(a.projectId).id);return'正在按项目目标进行本地初筛'};
ACT['library.add']=a=>sbAdd(rp(a.projectId),a.resourceId,'reference');
ACT['library.remove']=a=>sbRemove(rp(a.projectId),a.resourceId);
paramLabels.resourceId='方法编号（能力库中可查看）';paramLabels.query='关键词';paramLabels.category='分类编号（可选）';
const sbCtx=ctx;ctx=function(){const c=sbCtx();c.library=[...new Map([...sbRefs(P(state.room)||P(state.sel)),...SB.entries,...SB.recommendations.map(x=>x.entry)].map(e=>[e.id,e])).values()].slice(0,60).map(e=>({id:e.id,title:e.title,kind:e.kind}));return c};
function sbAdd(p,id,mode,guide){const entry=SB.known.get(id)||sbRefs(p).find(r=>r.id===id);if(!entry)throw'先在能力库搜索或查看此条目';if(entry.historical)throw'此条目已归档或移除，请查看来源';const refs=sbRefs(p);if(!refs.some(r=>r.id===id)&&refs.length>=40)throw'每个项目最多保存 40 项方法，请先整理';if(mode==='guide'&&(!guide||guide.id!==id||!guide.bodyHash))throw'先读取指南正文';pushUndo();p.skillRefs=[...refs.filter(r=>r.id!==id),{id,title:entry.title,url:entry.url,mode,referenceRevision:entry.revision,bodyHash:mode==='guide'?guide.bodyHash:undefined,addedOn:new Date().toISOString()}];save();sbRefreshProject();return'已加入「'+p.name+'」'+(mode==='guide'?'的 Prompt 指南':'的项目参考');}
function sbRemove(p,id){if(!sbRefs(p).some(r=>r.id===id))throw'项目未引用此条目';pushUndo();p.skillRefs=sbRefs(p).filter(r=>r.id!==id);save();sbRefreshProject();return'已移除方法引用';}
function sbRefreshProject(){if(skillbook.open)sbPaint();if(panK==='proj')renderPan();/* Keep a room draft and its caret in place. */const p=P(state.room);if(p){const det=$('#room .det');const pins=det?.querySelector('.sb-pins');if(pins)pins.innerHTML=sbPins(p);const btn=$('#room .rh [data-sb-open]');if(btn)btn.innerHTML=icon('layers')+'能力库'+(sbRefs(p).length?' · '+sbRefs(p).length:'');}}
function sbOpen(projectId,reset=true){SB.projectId=projectId?rp(projectId).id:(P(state.room)||P(state.sel))?.id||null;SB.epoch++;SB.detail=null;SB.guide=null;SB.notice='';if(reset){SB.query='';SB.category='';SB.kind='';SB.page=1;}if(!skillbook.open)skillbook.showModal();sbPaint();sbSearch();sbStatus();sbRecommend(false);}
function sbClose(){SB.epoch++;SB.searchAC?.abort();SB.recommendAC?.abort();SB.detailAC?.abort();skillbook.close();}
function sbPaint(){
 const focused=document.activeElement?.closest('#skillbook')&&document.activeElement.id,selection=focused&&document.activeElement.selectionStart;
 const p=sbProject(),s=SB.stats,refs=sbRefs(p),d=SB.detail;skillbook.style.setProperty('--project-color',p?.ui.color||'#7773B8');
 skillbook.innerHTML=`<header class="sb-head"><div class="sb-emblem">${icon('layers',26)}</div><div><span class="sb-eyebrow">每个项目，都有适合的方法</span><h2>能力与工作流</h2></div><button class="x" data-sb="close" aria-label="关闭能力库">${icon('close',20)}</button></header>
 <div class="sb-layout"><aside class="sb-context"><label for="sb-project">为哪个项目找方法？</label><select id="sb-project"><option value="">先随便逛逛</option>${state.projects.map(x=>`<option value="${x.id}" ${x.id===SB.projectId?'selected':''}>${esc(state.boards.find(b=>b.id===x.boardId)?.name||'')} / ${esc(x.name)}</option>`).join('')}</select>
 ${p?`<label for="sb-goal">这个项目想完成什么</label><textarea id="sb-goal" placeholder="例如：每周从货运数据生成 Excel 报表和汇报 PPT">${esc(SB.goalDrafts.get(p.id)??p.summary??'')}</textarea><button data-sb="goal">保存目标并推荐</button><div class="sb-section-title">已选方法 <span>${refs.length}</span></div><div class="sb-saved">${refs.map(r=>`<div><button class="sb-text-button" data-sb-id="${esc(r.id)}">${esc(r.title)}</button><small>${r.mode==='guide'?'已读取 · 版本 '+r.bodyHash?.slice(0,7):'仅项目参考'}</small><button class="x" data-sb-remove="${esc(r.id)}" aria-label="移除 ${esc(r.title)}">×</button></div>`).join('')||'<p class="sb-muted">看到合适的，放进这个项目。<br>不同项目可以选择不同方法。</p>'}</div>`:'<p class="sb-muted">选择项目后，会按目标、职责和文件类型初筛；也可以自由浏览。</p>'}
 <div class="sb-update" id="sb-status">${sbStatusHTML()}</div></aside><main class="sb-main">
 <form id="sb-search-form" class="sb-search"><input id="sb-query" value="${esc(SB.query)}" placeholder="搜索：调试、Excel、演示、研究、自动化…" aria-label="搜索能力库"><button type="submit">${icon('search',16)}查找</button></form>
 <div class="sb-categories"><button data-sb-cat="" aria-pressed="${!SB.category}">全部</button>${SB.categories.map(c=>`<button data-sb-cat="${c.id}" aria-pressed="${SB.category===c.id}">${esc(c.title)}</button>`).join('')}</div>
 <div class="sb-filters"><label>类型 <select id="sb-kind"><option value="">全部</option>${SB.kinds.map(k=>`<option value="${esc(k)}" ${SB.kind===k?'selected':''}>${esc(sbKinds[k]||k)}</option>`).join('')}</select></label><label><input id="sb-open-only" type="checkbox" ${SB.openOnly?'checked':''}>仅声明开源</label><label><input id="sb-history" type="checkbox" ${SB.includeHistorical?'checked':''}>包含归档</label></div>
 <div class="sb-notice" role="status">${esc(SB.notice)}</div>
 ${d?sbDetailHTML(d):`${p&&!SB.query&&!SB.category&&!SB.kind?`<section class="sb-recommend"><div class="sb-section-title">${icon('sparkles',17)}为「${esc(p.name)}」挑选 <button data-sb="recommend">重新初筛</button><button data-sb="semantic" ${SB.busy?'disabled':''}>${SB.busy?'判断中…':'统筹进一步判断 · 联网'}</button>${SB.busy?'<button data-sb="stop">停止</button>':''}</div><p class="sb-muted">${esc(SB.recMessage||'本地初筛不调用模型；联网判断仅发送目标、职责、文件扩展名和候选目录。')}</p><div class="sb-rec-grid">${SB.recommendations.map(x=>sbCard(x.entry,x.reason,x.adaptation)).join('')||'<p class="sb-muted">保存清晰的项目目标，就能找到更合适的方法。</p>'}</div></section>`:''}
 <div class="sb-section-title">浏览资料库 <span>${SB.total.toLocaleString()} 条匹配</span>${s?`<small>${s.sources} 个来源 · ${s.upstreamEntries.toLocaleString()} 条索引 + ${s.localMethods} 项适配方法</small>`:''}</div>
 <div class="sb-results">${SB.entries.map(e=>sbCard(e)).join('')||'<p class="sb-muted">没有匹配条目，换个词或清除筛选试试。</p>'}</div><div class="sb-pagination"><button data-sb="prev" ${SB.page<=1?'disabled':''}>上一页</button><span>${SB.page} / ${Math.max(1,Math.ceil(SB.total/18))}</span><button data-sb="next" ${SB.page*18>=SB.total?'disabled':''}>下一页</button></div>`}
 </main></div>`;
 if(focused){const el=document.getElementById(focused);if(el){el.focus();if(typeof selection==='number'&&el.setSelectionRange)el.setSelectionRange(selection,selection);}}
}
function sbCard(e,reason,adaptation){const saved=sbRefs(sbProject()).some(r=>r.id===e.id);return`<article class="sb-card" style="--tile:${({development:'#DEE6FF',design:'#E9DFFC',documents:'#E4EDDF',spreadsheets:'#D8EFE3',slides:'#F7E2CC',automation:'#E0E8F0',research:'#E4E1F5'})[e.categories[0]]||'#F0E9D8'}"><button class="sb-card-open" data-sb-id="${esc(e.id)}"><span class="sb-card-symbol">${icon(e.kind==='workflow'?'link':'layers',18)}</span><span><b>${esc(e.title)}</b><small>${esc(sbKinds[e.kind]||e.kind)} · ${esc(e.sourceId)}</small></span>${saved?'<span class="sb-check">✓</span>':''}</button><p>${esc(reason||e.description)}</p>${adaptation?`<p class="sb-muted">${esc(adaptation)}</p>`:''}<footer><span>${e.historical?'归档 / 已移除':sbReview(e)}</span><button data-sb-id="${esc(e.id)}">查看</button></footer></article>`;}
function sbDetailHTML(e){const g=SB.guide,ref=sbRefs(sbProject()).find(r=>r.id===e.id);return`<section class="sb-detail"><button data-sb="back">${icon('back',14)}返回浏览</button><span class="sb-eyebrow">${esc(sbKinds[e.kind]||e.kind)} · ${esc(e.sourceId||'项目保留记录')}</span><h2>${esc(e.title)}</h2><p>${esc(e.description||'此项目保留的方法引用。')}</p><div class="sb-badges"><span>${e.review?sbReview(e):'项目保留版本'}</span><span>${esc(e.license||'许可待核实')}</span>${e.historical?'<span>来源已归档 / 条目已移除</span>':''}</div><div class="sb-actions"><a href="${esc(e.url)}" target="_blank" rel="noreferrer">查看原始来源 ↗</a>${sbProject()?`<button data-sb="add">${ref?'保留为项目参考':'加入项目参考'}</button>`:''}<button data-sb="read" ${e.historical?'disabled':''}>读取当前指南</button>${g&&sbProject()?'<button class="sb-primary" data-sb="use">用作项目 Prompt 指南</button>':''}</div><p class="sb-muted">参考条目不会自动执行。读取会核对来源内容与许可；被项目采用的指南保留版本，供 Prompt 优化按本次请求选择。</p>${ref?.bodyHash?`<p class="sb-muted">项目当前保留版本 ${esc(ref.bodyHash.slice(0,12))}；目录更新不替换它。</p>`:''}<details><summary>条目编号</summary><code>${esc(e.id)}</code></details>${g?`<div class="sb-guide-meta">已读取 · ${esc(g.cachedOn)} · 版本 ${esc(g.bodyHash.slice(0,12))}</div><pre class="sb-guide-body">${esc(g.body)}</pre><details><summary>来源许可</summary><pre class="sb-guide-body">${esc(g.licenseText)}</pre></details>`:''}</section>`;}
function sbStatusHTML(){const s=SB.status;if(!s)return'读取更新状态…';const u=s.update,failed=u?.results?.filter(r=>['failed','directory-deferred'].includes(r.state))||[];return`<b>持续生长的资料库</b><p>${s.schedule.state==='ACTIVE'?'每周五 17:00 · 伦敦时间':s.schedule.state==='PAUSED'?'每周更新已暂停':'每周任务状态待确认'}</p><small>${s.schedule.hostRequired?'由已检测到的宿主任务更新，电脑和应用需保持可运行。':'尚未检测到定时任务。可手动更新，或自行配置每周调度。'}</small><p>目录检查：${esc(s.lastCatalogCheck||'尚无记录')}<br>${({running:'正在检查来源…',completed:'最近更新完成',partial:'部分来源待重试，保留旧条目',failed:'最近更新失败，保留有效目录',cancelled:'已停止更新，保留有效目录'})[u?.state]||'尚未更新'}</p><div class="row"><button data-sb="status">刷新状态</button><button data-sb="refresh" ${u?.state==='running'?'disabled':''}>更新目录</button>${s.cancellable?'<button data-sb="cancel-refresh">停止更新</button>':''}</div>${failed.length?`<details><summary>${failed.length} 个来源需重试</summary>${failed.map(r=>`<p>${esc(r.id)}：${esc(r.error||'稍后重试')}</p>`).join('')}</details>`:''}<small>收录、读取与运行验证分别记录。</small>`;}
async function sbStatus(){try{SB.status=await sbApi('status');if(skillbook.open&&$('#sb-status'))$('#sb-status').innerHTML=sbStatusHTML();}catch(e){sbNotice(e.message);}}
function sbNotice(message){SB.notice=message;const el=skillbook.querySelector('.sb-notice');if(el)el.textContent=message;}
async function sbSearch(){SB.searchAC?.abort();const ac=SB.searchAC=new AbortController(),epoch=SB.epoch;sbNotice('正在检索…');try{const d=await sbApi('search',{query:SB.query,category:SB.category||undefined,kind:SB.kind||undefined,page:SB.page,pageSize:18,openOnly:SB.openOnly,includeHistorical:SB.includeHistorical},ac.signal);if(ac.signal.aborted||epoch!==SB.epoch)return;Object.assign(SB,{entries:d.entries,total:d.total,stats:d.stats,categories:d.categories,kinds:d.kinds,notice:'',goalDrafts:new Map()});sbRemember(d.entries);sbPaint();}catch(e){if(!ac.signal.aborted&&epoch===SB.epoch)sbNotice(e.message);}}
async function sbRecommend(semantic){SB.recommendAC?.abort();const p=sbProject();SB.recommendations=[];if(!p){sbPaint();return;}const ac=SB.recommendAC=new AbortController(),epoch=SB.epoch;SB.busy=semantic;SB.recMessage=semantic?'统筹正在判断，可随时停止…':'正在按项目目标初筛…';sbPaint();try{const d=await sbApi(semantic?'semantic':'recommend',{project:sbNeeds(p)},ac.signal);if(ac.signal.aborted||epoch!==SB.epoch||sbProject()!==p)return;SB.recommendations=d.items;SB.recMessage=(d.mode==='local'?'本地初筛 · ':'统筹判断 · ')+d.message;sbRemember(d.items.map(x=>x.entry));}catch(e){if(epoch===SB.epoch)SB.recMessage=ac.signal.aborted?'已停止，已选方法保留。':e.message;}finally{if(SB.recommendAC===ac)SB.busy=false;if(epoch===SB.epoch&&skillbook.open)sbPaint();}}
async function sbRead(){const d=SB.detail;if(!d)return;SB.detailAC?.abort();const ac=SB.detailAC=new AbortController(),epoch=SB.epoch;sbNotice('正在读取指南与核对许可…');try{const g=await sbApi('guide',{id:d.id},ac.signal);if(epoch!==SB.epoch||SB.detail?.id!==d.id||ac.signal.aborted)return;SB.guide=g;d.bodyReadOn=g.cachedOn;if(/Apache License/i.test(g.licenseText))d.license='Apache-2.0';else if(/Permission is hereby granted/i.test(g.licenseText))d.license='MIT';SB.known.set(d.id,d);SB.notice='已读取正文，尚未执行';sbPaint();}catch(e){if(!ac.signal.aborted&&epoch===SB.epoch)sbNotice(e.message);}}
skillbook.addEventListener('cancel',e=>{e.preventDefault();sbClose();});
skillbook.addEventListener('submit',e=>{if(e.target.id!=='sb-search-form')return;e.preventDefault();SB.query=$('#sb-query').value;SB.page=1;SB.detail=null;sbSearch();});
skillbook.addEventListener('input',e=>{if(e.target.id==='sb-query')SB.query=e.target.value;if(e.target.id==='sb-goal'&&SB.projectId)SB.goalDrafts.set(SB.projectId,e.target.value);});
skillbook.addEventListener('change',e=>{const t=e.target;if(t.id==='sb-project'){SB.projectId=t.value||null;SB.epoch++;SB.detail=null;SB.guide=null;sbPaint();sbRecommend(false);}else if(['sb-kind','sb-open-only','sb-history'].includes(t.id)){SB.kind=$('#sb-kind').value;SB.openOnly=$('#sb-open-only').checked;SB.includeHistorical=$('#sb-history').checked;SB.page=1;SB.detail=null;sbSearch();}});
document.addEventListener('click',async e=>{const opener=e.target.closest('[data-sb-open]');if(opener){sbOpen(opener.dataset.sbOpen||undefined);return;}const t=e.target.closest('#skillbook button');if(!t)return;
 try{if(t.hasAttribute('data-sb-cat')){SB.category=t.dataset.sbCat;SB.page=1;SB.detail=null;sbSearch();return;}
 if(t.dataset.sbId){SB.detailAC?.abort();SB.detail=SB.known.get(t.dataset.sbId)||sbRefs(sbProject()).find(r=>r.id===t.dataset.sbId);SB.guide=null;sbPaint();return;}
 if(t.dataset.sbRemove){hint(sbRemove(sbProject(),t.dataset.sbRemove));return;}
 switch(t.dataset.sb){case'close':sbClose();break;case'back':SB.detailAC?.abort();SB.detail=null;SB.guide=null;sbPaint();break;case'prev':SB.page=Math.max(1,SB.page-1);sbSearch();break;case'next':SB.page++;sbSearch();break;case'goal':{const p=sbProject();if(!p)return;act('project.update',{projectId:p.id,summary:$('#sb-goal').value});SB.goalDrafts.delete(p.id);sbRecommend(false);break;}case'recommend':sbRecommend(false);break;case'semantic':sbRecommend(true);break;case'stop':SB.recommendAC?.abort();break;case'add':hint(sbAdd(sbProject(),SB.detail.id,'reference'));break;case'remove':hint(sbRemove(sbProject(),SB.detail.id));break;case'read':sbRead();break;case'use':hint(sbAdd(sbProject(),SB.detail.id,'guide',SB.guide));break;case'status':sbStatus();break;case'refresh':SB.status=await sbApi('refresh');$('#sb-status').innerHTML=sbStatusHTML();break;case'cancel-refresh':SB.status=await sbApi('cancel-refresh');$('#sb-status').innerHTML=sbStatusHTML();break;}
 }catch(err){sbNotice(err.message||String(err));}
});
/* SKILL_LIBRARY_END */
